package com.bank.salarysort.service;

import com.bank.salarysort.model.Employee;
import java.util.Comparator;
import java.util.List;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class SalarySortService {
    private static final Logger log = Logger.getLogger(SalarySortService.class.getName());

    public List<Employee> bySalaryAscending(List<Employee> employees) {
        log.info(() -> "Sorting " + employees.size() + " employees by salary ascending");
        return employees.stream()
                // comparing uses BigDecimal.compareTo → exact ascending order.
                .sorted(Comparator.comparing(Employee::getSalary))
                .collect(Collectors.toList());
    }
}
