package com.bank.salarysort;

import com.bank.salarysort.model.Employee;
import com.bank.salarysort.service.SalarySortService;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;

public class Main {
    private static final Logger log = Logger.getLogger(Main.class.getName());

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", new BigDecimal("95000")),
            new Employee("Priya",  new BigDecimal("72000")),
            new Employee("Amit",   new BigDecimal("48000")),
            new Employee("Neha",   new BigDecimal("60000"))
        );

        new SalarySortService().bySalaryAscending(staff)
            .forEach(e -> log.info(() -> "Ascending: " + e));
    }
}
